Read the target date from Sheet1!C5 and find the matching date in Sheet2 row 5. Collect the items present in that Sheet2 column, then write each Sheet1 item if present or NEW if absent into C6:C31. Save the workbook with plain values.

```python
import shutil
import openpyxl
from datetime import datetime, date

try:
    from openpyxl.utils.datetime import from_excel
except Exception:
    from_excel = None

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

s1v = vals["Sheet1"]
s2v = vals["Sheet2"]
s1 = wb["Sheet1"]

def to_date(v):
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, (int, float)) and from_excel is not None:
        try:
            return from_excel(v).date()
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        for fmt in (
            "%Y-%m-%d",
            "%Y/%m/%d",
            "%m/%d/%Y",
            "%d/%m/%Y",
            "%d-%m-%Y",
            "%Y-%m-%d %H:%M:%S",
        ):
            try:
                return datetime.strptime(s, fmt).date()
            except Exception:
                pass
    return None

target = to_date(s1v["C5"].value)

col = None
for c in range(1, s2v.max_column + 1):
    d = to_date(s2v.cell(row=5, column=c).value)
    if target is not None and d == target:
        col = c
        break

if col is None:
    if target is not None:
        best = None
        best_diff = None
        for c in range(1, s2v.max_column + 1):
            d = to_date(s2v.cell(row=5, column=c).value)
            if d is not None:
                diff = abs((d - target).days)
                if best_diff is None or diff < best_diff:
                    best_diff = diff
                    best = c
        col = best
    else:
        col = 6

if col is None:
    col = 6

present = set()
for r in range(6, s2v.max_row + 1):
    v = s2v.cell(row=r, column=col).value
    if v is not None:
        s = str(v).strip()
        if s:
            present.add(s)

for r in range(6, 32):
    b = s1v.cell(row=r, column=2).value
    if b is None:
        s1.cell(row=r, column=3).value = None
        continue

    bstr = str(b).strip()
    if not bstr:
        s1.cell(row=r, column=3).value = None
    else:
        s1.cell(row=r, column=3).value = bstr if bstr in present else "NEW"

wb.save(OUT)

print("target_date:", target, "selected_col:", col)
print("present_items:", sorted(present))
print("first_values:", [s1.cell(row=r, column=3).value for r in range(6, 12)])
